// Independent ICU79.1 oracle corpora for Sounio's public CLDR locale API.
#define SOUNIO_CLDR_GRAPH_ORACLE_NO_MAIN
#include "cldr_graph_oracle.cpp"
#include <span>
using Lbytes=std::vector<std::uint8_t>;
void lword(Lbytes&out,std::uint32_t value){for(unsigned i=0;i<4;++i)out.push_back(static_cast<std::uint8_t>(value>>(8*i)));}
void lsequence(Lbytes&out,const Fseq&text){if(text.size()>4096)bad("locale fixture sequence budget");lword(out,static_cast<std::uint32_t>(text.size()));for(auto cp:text){if(cp>0x10ffff||(cp>=0xd800&&cp<=0xdfff))bad("non-scalar locale fixture input");lword(out,cp);}}
Fseq lascii(const std::string&s){Fseq out;for(unsigned char c:s){if(c>=128)bad("non-ASCII locale identity");out.push_back(c);}return out;}
struct Lwriter{
 fs::path directory;std::ofstream manifest;Lbytes payload;std::uint32_t rows=0,index=0;std::uint64_t total=0;
 explicit Lwriter(fs::path p):directory(std::move(p)){if(!fs::create_directory(directory))bad("locale fixture output must be new");manifest.open(directory/"MANIFEST.tsv");manifest<<"filename\tkind\trows\tpayload_bytes\n";}
 void flush(){if(!rows)return;if(index>=1000000)bad("locale fixture filename extent");std::ostringstream name;name<<"locale-"<<std::setw(6)<<std::setfill('0')<<index++<<".bin";Lbytes all{'S','O','U','N','U','T','F','1'};lword(all,5);lword(all,rows);lword(all,static_cast<std::uint32_t>(payload.size()));lword(all,0x00120000);all.insert(all.end(),payload.begin(),payload.end());std::ofstream out(directory/name.str(),std::ios::binary);out.write(reinterpret_cast<const char*>(all.data()),static_cast<std::streamsize>(all.size()));if(!out)bad("locale fixture write");manifest<<name.str()<<"\t5\t"<<rows<<'\t'<<payload.size()<<'\n';payload.clear();rows=0;}
 void add(const Tailoring&t,const Fseq&a,const Fseq&b,const std::array<int,6>&options,int expected){Lbytes record;lsequence(record,lascii(t.locale));lsequence(record,lascii(t.type));lsequence(record,a);lsequence(record,b);for(auto value:options)lword(record,static_cast<std::uint32_t>(value));if(expected<-1||expected>1)bad("locale expected-order domain");lword(record,static_cast<std::uint32_t>(expected+1));if(record.size()>1048576)bad("oversized locale record");if(rows==512||payload.size()+record.size()>1048576)flush();payload.insert(payload.end(),record.begin(),record.end());++rows;++total;}
 void finish(const std::string&scope){flush();if(!total||!manifest)bad("empty locale corpus");manifest.close();std::ofstream out(directory/"SCOPE.txt");out<<scope<<"\nEvery public CLDR49 collation; no private or alt entry exposed as public.\nOriginal codepoints and every selected source row preserved; strict UTF8 scalar input.\nOracle normalization is ON: the production API always normalizes to NFD.\n";if(!out)bad("locale scope output");std::cout<<"CLDR_NATIVE_CORPUS_OK files="<<index<<" rows="<<total<<"\n";}
};
std::set<Fseq> l_samples(const Registry&registry,std::size_t id,const Fractional&fractional,bool options){
 const auto&t=registry.entries[id];std::set<Fseq> samples={{},{0},{0x61},{0x41},{0x61,0x301},{0xe9},{0x65,0x301},{0xfffe},{0xffff},{0x1f600},{0x4e00},{0x4e01},{0x3400},{0x378},{0x627},{0x3b1},{0x430},{0x3042},{0x30a2},{0x20},{0x21},{0x24},{0x2b},{0x61,0xfffe,0x62},{0x62,0xfffe,0x61},{0x61,0x301,0xfffe,0x62,0x300},{0x61,0x300,0xfffe,0x62,0x301}};
 std::set<std::size_t> visited;std::set<int> covered;
 std::function<void(std::size_t)> walk=[&](std::size_t entry){if(!visited.insert(entry).second)return;for(const auto&r:registry.entries[entry].rules){if(r.op==4){walk(registry.imported(r.text));continue;}if(r.op!=2)continue;int category=r.strength+(r.starred?10:0)+(!r.prefix.empty()?20:0)+(!r.extension.empty()?40:0);if(options&&!covered.insert(category).second)continue;if(r.starred){auto cps=fstarred(r.text);if(options){if(!cps.empty()){samples.insert({cps.front()});samples.insert({cps.back()});}}else for(auto cp:cps)samples.insert({cp});}else{auto text=fliteral(r.text);samples.insert(text);if(!r.prefix.empty()){auto prefix=fliteral(r.prefix);prefix.insert(prefix.end(),text.begin(),text.end());samples.insert(prefix);}if(!r.extension.empty())samples.insert(fliteral(r.extension));}}};walk(id);
 if(!options&&t.locale=="root"&&t.type=="standard"){
  for(const auto&[key,ces]:fractional.entries){(void)ces;auto text=key.prefix;text.insert(text.end(),key.text.begin(),key.text.end());samples.insert(text);
   if(key.text.size()>1)for(std::size_t at=1;at<text.size();++at)for(auto mark:Fseq{0x334,0x327,0x300,0x345}){auto extra=text;extra.insert(extra.begin()+static_cast<std::ptrdiff_t>(at),mark);samples.insert(std::move(extra));}}
  for(auto cp:fractional.radical)samples.insert({cp});
 }
 return samples;
}
void l_configure(UCollator*c,const Gsettings&config){UErrorCode e=U_ZERO_ERROR;ucol_setAttribute(c,UCOL_STRENGTH,config.strength==5?UCOL_IDENTICAL:static_cast<UColAttributeValue>(config.strength-1),&e);ucol_setAttribute(c,UCOL_ALTERNATE_HANDLING,config.shifted?UCOL_SHIFTED:UCOL_NON_IGNORABLE,&e);ucol_setAttribute(c,UCOL_FRENCH_COLLATION,config.backwards?UCOL_ON:UCOL_OFF,&e);ucol_setAttribute(c,UCOL_CASE_LEVEL,config.case_level?UCOL_ON:UCOL_OFF,&e);ucol_setAttribute(c,UCOL_CASE_FIRST,config.case_first==2?UCOL_UPPER_FIRST:config.case_first==1?UCOL_LOWER_FIRST:UCOL_OFF,&e);ucol_setAttribute(c,UCOL_NORMALIZATION_MODE,UCOL_ON,&e);const std::map<std::string,UColReorderCode> variable{{"space",UCOL_REORDER_CODE_SPACE},{"punct",UCOL_REORDER_CODE_PUNCTUATION},{"symbol",UCOL_REORDER_CODE_SYMBOL},{"currency",UCOL_REORDER_CODE_CURRENCY}};ucol_setMaxVariable(c,variable.at(config.max_variable),&e);if(U_FAILURE(e))bad("locale fixture ICU settings");}
int main(int argc,char**argv){try{if(argc!=5)return 64;std::string mode=argv[4];if(mode!="defaults"&&mode!="options")return 64;bool options=mode=="options";g_oracle_versions();cldr_input_versions(argv[1],argv[2]);Registry registry(argv[1]);Fractional fractional(fs::path(argv[1])/"common/uca/FractionalUCA.txt");Fnormalize normalizer(argv[2]);Lwriter out(argv[3]);std::uint64_t locales=0,comparisons=0;
 for(std::size_t id=0;id<registry.entries.size();++id){const auto&t=registry.entries[id];if(t.type.starts_with("private-")||!t.variant.empty())continue;Fbuilder builder(fractional,normalizer);builder.apply(registry,id);auto samples=l_samples(registry,id,fractional,options);for(const auto&sample:samples)builder.lookup(normalizer.nfd(sample));Gprepared prepared(builder);auto oracle=g_compile(t);UErrorCode normalization_status=U_ZERO_ERROR;ucol_setAttribute(oracle,UCOL_NORMALIZATION_MODE,UCOL_ON,&normalization_status);if(U_FAILURE(normalization_status))bad("locale oracle NFD contract");std::vector<Gsettings> configurations{builder.settings};if(options){configurations.clear();for(unsigned s=1;s<=5;++s)for(unsigned a=0;a<2;++a)for(unsigned b=0;b<2;++b)for(unsigned cl=0;cl<2;++cl)for(unsigned cf=0;cf<3;++cf)for(const auto&variable:std::vector<std::string>{"space","punct","symbol","currency"}){auto config=builder.settings;config.strength=s;config.shifted=a!=0;config.backwards=b!=0;config.case_level=cl!=0;config.case_first=cf;config.max_variable=variable;configurations.push_back(config);}}
  for(const auto&config:configurations){builder.settings=config;prepared.set_variable(config.max_variable);if(options)l_configure(oracle,config);std::vector<std::pair<std::vector<std::uint8_t>,Fseq>> sorted;for(const auto&sample:samples)sorted.emplace_back(g_icu_key(oracle,sample),sample);std::sort(sorted.begin(),sorted.end());for(std::size_t i=1;i<sorted.size();++i){int expected=sorted[i-1].first<sorted[i].first?-1:0;auto a=g_key(builder,sorted[i-1].second,prepared),b=g_key(builder,sorted[i].second,prepared);int actual=a<b?-1:b<a?1:0;if(actual!=expected){std::cerr<<"LOCALE_GRAPH_PROBE "<<Registry::identity(t.locale,t.type,t.variant)<<" LEFT "<<display(sorted[i-1].second)<<" RIGHT "<<display(sorted[i].second)<<" expected="<<expected<<" actual="<<actual<<"\n";bad("extended locale graph oracle");}std::array<int,6> settings{-1,-1,-1,-1,-1,-1};if(options){const std::map<std::string,int> variables{{"space",0},{"punct",1},{"symbol",2},{"currency",3}};settings={static_cast<int>(config.strength),config.shifted?1:0,config.backwards?1:0,config.case_level?1:0,static_cast<int>(config.case_first),variables.at(config.max_variable)};}out.add(t,sorted[i-1].second,sorted[i].second,settings,expected);++comparisons;}}
  ucol_close(oracle);++locales;std::cout<<"CLDR_NATIVE_LOCALE_FIXTURES_OK "<<Registry::identity(t.locale,t.type,t.variant)<<" samples="<<samples.size()<<" configurations="<<configurations.size()<<"\n";
 }
 if(locales!=154||!comparisons)bad("missing public CLDR49 locale domain");out.finish(options?"PUBLIC_CLDR49_COMPLETE_480_OPTION_MATRIX_ON_DECLARED_BRANCH_PROBES":"PUBLIC_CLDR49_ALL_SOURCE_DEFAULTS_ROOT_ALL_MAPPINGS_RADICALS_AND_DISCONTIGUOUS_PROBES");std::cout<<"CLDR_NATIVE_GENERATOR_OK public_entries="<<locales<<" comparisons="<<comparisons<<" mode="<<mode<<"\n";return 0;
}catch(const std::exception&e){std::cerr<<"CLDR_NATIVE_GENERATOR_ERROR "<<e.what()<<"\n";return 1;}}
